/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, I, Mul, isEulerJacobiPseudoprime, isExtraStrongLucasPrp, isFermatPseudoprime, isGaussianPrime, isMersennePrime, isSquare, isUnsolved, isprime, mr, prothTest, rational } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.ntheory.primetest", () => {
  it("is_mersenne_prime(6)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_mersenne_prime(127)", () => {
    expect(sympyStr(isMersennePrime(rational(127)))).toBe('True');
  });
  it("isprime(13)", () => {
    expect(sympyStr(isprime(rational(13)))).toBe('True');
  });
  it("isprime(15)", () => {
    expect(sympyStr(isprime(rational(15)))).toBe('False');
  });
  it("near_int == int(near_int)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("n % 1 == 0", () => {
    expect(sympyStr(rational(0).equals(rational(0)))).toBe('True');
  });
  it("n % 1 == 0 (2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_square(25)", () => {
    expect(sympyStr(isSquare(rational(25)))).toBe('True');
  });
  it("is_square(2)", () => {
    expect(sympyStr(isSquare(rational(2)))).toBe('False');
  });
  it("mr(1373651, [2, 3])", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("mr(479001599, [31, 73])", () => {
    expect(sympyStr(mr(rational(479001599), [31, 73]))).toBe('True');
  });
  it("proth_test(41)", () => {
    expect(sympyStr(prothTest(rational(41)))).toBe('True');
  });
  it("proth_test(57)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
});

